type Deposito struct {
	mu     sync.Mutex
	envios []Envio
}

func (d *Deposito) Uno(id int) (Envio, bool) {
	d.mu.Lock()
	defer d.mu.Unlock()
	for _, e := range d.envios {
		if e.ID == id {
			return e, true
		}
	}
	return Envio{}, false
}

func (d *Deposito) Agregar(e Envio) Envio {
	d.mu.Lock()
	defer d.mu.Unlock()
	e.ID = len(d.envios) + 1
	d.envios = append(d.envios, e)
	return e
}

// Un middleware en Go es una función que recibe un manejador y devuelve otro.
func medir(sig http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		t0 := time.Now()
		sig.ServeHTTP(w, r)
		log.Printf("%s %s en %v", r.Method, r.URL.Path, time.Since(t0))
	})
}

func main() {
	dep := &Deposito{envios: []Envio{
		{1, "Rosario", 12.5, "en_deposito"},
		{2, "Mendoza", 40, "despachado"},
	}}
	mux := http.NewServeMux()

	mux.HandleFunc("GET /envios/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, err := strconv.Atoi(r.PathValue("id"))
		if err != nil {
			http.NotFound(w, r)
			return
		}
		e, ok := dep.Uno(id)
		if !ok {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(e)
	})

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct NuevoEnvio {
    destino: String,
    peso_kg: f64,
}

type Deposito = Arc<Mutex<Vec<Envio>>>;

async fn uno(State(dep): State<Deposito>, Path(id): Path<u32>) -> Result<Json<Envio>, StatusCode> {
    let envios = dep.lock().unwrap();
    envios.iter().find(|e| e.id == id).cloned().map(Json).ok_or(StatusCode::NOT_FOUND)
}

async fn crear(State(dep): State<Deposito>, Json(n): Json<NuevoEnvio>) -> Response {
    if n.destino.is_empty() || n.peso_kg < 0.1 || n.peso_kg > 1000.0 {
        return (StatusCode::BAD_REQUEST, "destino obligatorio y peso entre 0,1 y 1000").into_response();
    }
    let mut envios = dep.lock().unwrap();
    let e = Envio { id: envios.len() as u32 + 1, destino: n.destino, peso_kg: n.peso_kg, estado: "en_deposito".into() };
    envios.push(e.clone());
    (StatusCode::CREATED, Json(e)).into_response()
}
